1	/**
2	 * Sininho de notificações master no header.
3	 * - Subscribe Realtime na tabela notificacoes_master
4	 * - Dropdown com últimas 10 não-lidas + ações inline
5	 * - Atualiza badge em tempo real
6	 */
7	
8	import { useEffect, useState } from 'react';
9	import { useNavigate } from 'react-router-dom';
10	import {
11	  Bell,
12	  Plane,
13	  UserMinus,
14	  Gavel,
15	  AlertCircle,
16	  ClipboardCheck,
17	  Wind,
18	} from 'lucide-react';
19	import { supabase } from '@/integrations/supabase/client';
20	import { Button } from '@/shared/ui/button';
21	import {
22	  DropdownMenu,
23	  DropdownMenuContent,
24	  DropdownMenuTrigger,
25	} from '@/shared/ui/dropdown-menu';
26	import { useIsRhMaster } from '../lib/permissions';
27	import type { NotificacaoMaster, NotificacaoMasterTipo } from '../types';
28	
29	const TIPO_ICON: Record<NotificacaoMasterTipo, React.ComponentType<{ className?: string }>> = {
30	  ferias_solicitacao: Plane,
31	  ferias_aprovada: Plane,
32	  ferias_rejeitada: Plane,
33	  ferias_aviso_pendente_assinatura: Plane,
34	  desligamento_solicitado: UserMinus,
35	  desligamento_realizado: UserMinus,
36	  punitivo_cadastrado: Gavel,
37	  experiencia_decisao: AlertCircle,
38	  pesquisa_saida_preenchida: ClipboardCheck,
39	  pesquisa_clima_resposta: Wind,
40	};
41	
42	const TIPO_ROUTE: Record<NotificacaoMasterTipo, string> = {
43	  ferias_solicitacao: '/funcionarios/ferias',
44	  ferias_aprovada: '/funcionarios/ferias',
45	  ferias_rejeitada: '/funcionarios/ferias',
46	  ferias_aviso_pendente_assinatura: '/funcionarios/ferias',
47	  desligamento_solicitado: '/funcionarios/desligamentos',
48	  desligamento_realizado: '/funcionarios/desligamentos',
49	  punitivo_cadastrado: '/funcionarios/metodos-punitivos',
50	  experiencia_decisao: '/funcionarios/experiencia',
51	  pesquisa_saida_preenchida: '/funcionarios/pesquisa-saida',
52	  pesquisa_clima_resposta: '/funcionarios/pesquisa-clima',
53	};
