177	// ─────────────────────────────────────────────────────────────────────────────
178	// Vendas defasadas (Linx via historico_vendas — último dia disponível)
179	// ─────────────────────────────────────────────────────────────────────────────
180	
181	interface LaggedSales {
182	  lojaId: number;
183	  /** Último dia com venda registrada (YYYY-MM-DD). */
184	  dataReferencia: string;
185	  valor: number;
186	  quantidade: number;
187	  /** Valor do MESMO DIA da semana anterior ao dia de referência, ou null. */
188	  valorSemanaAnterior: number | null;
189	}
190	
191	async function fetchLaggedStore(lojaId: number): Promise<LaggedSales | null> {
192	  // 1) Último dia com dado para a loja
193	  const { data: latest, error: latestErr } = await supabase
194	    .from('historico_vendas')
195	    .select('data')
196	    .eq('loja_id', lojaId)
197	    .order('data', { ascending: false })
198	    .limit(1);
199	  if (latestErr) throw latestErr;
200	  const refDate = latest?.[0]?.data;
201	  if (!refDate) return null;
202	
203	  const prevDate = toIsoDateLocal(addDays(parseIsoDateLocal(refDate), -7));
204	
205	  // 2) Vendas do dia de referência + mesmo dia da semana anterior
206	  const [curRes, prevRes] = await Promise.all([
207	    supabase
208	      .from('historico_vendas')
209	      .select('valor_total, quantidade')
210	      .eq('loja_id', lojaId)
211	      .eq('data', refDate)
212	      .limit(2000),
213	    supabase
214	      .from('historico_vendas')
215	      .select('valor_total')
216	      .eq('loja_id', lojaId)
217	      .eq('data', prevDate)
218	      .limit(2000),
219	  ]);
220	  if (curRes.error) throw curRes.error;
221	  if (prevRes.error) throw prevRes.error;
222	
223	  const valor = (curRes.data ?? []).reduce((s, r) => s + (r.valor_total ?? 0), 0);
224	  const quantidade = (curRes.data ?? []).reduce(
225	    (s, r) => s + (r.quantidade ?? 0),
226	    0,
227	  );
228	  const prevRows = prevRes.data ?? [];
229	  const valorSemanaAnterior =
230	    prevRows.length > 0
231	      ? prevRows.reduce((s, r) => s + (r.valor_total ?? 0), 0)
232	      : null;
233	
234	  return { lojaId, dataReferencia: refDate, valor, quantidade, valorSemanaAnterior };
235	}
236	
237	async function fetchLaggedSales(ctx: TvContext): Promise<LaggedSales[]> {
238	  const results = await Promise.all(ctx.linxLojaIds.map(fetchLaggedStore));
239	  return results.filter((r): r is LaggedSales => r !== null);
240	}
