251	  const { data, error } = await supabase
252	    .from('degust_vendas_diarias')
253	    .select('loja_id, valor_total')
254	    .eq('data', lastWeekDate)
255	    .in('loja_id', ids)
256	    .limit(5000);
257	  if (error) throw error;
258	  for (const row of data ?? []) {
259	    out.set(row.loja_id, (out.get(row.loja_id) ?? 0) + (row.valor_total ?? 0));
260	  }
261	  return out;
262	}
