401	// ─────────────────────────────────────────────────────────────────────────────
402	// Hook principal
403	// ─────────────────────────────────────────────────────────────────────────────
404	
405	/** Retorno do {@link useTvDashboardData}. */
406	export interface TvDashboardData {
407	  network: TvNetworkSummary | null;
408	  stores: TvStoreData[];
409	  factory: TvFactoryData | null;
410	  exceptions: TvExceptionsResult;
411	  topProducts: TvTopProduct[];
412	  freshness: TvFreshness;
413	  /** true enquanto o contexto (lojas/canais) ainda não carregou. */
